public class BasicDeserializerFactory__addExplicitAnyCreator_TriageGen2Test {

    private BasicDeserializerFactory factory;
    private DeserializationContext ctxt;
    private BeanDescription beanDesc;
    private CreatorCollector creators;

    // Concrete subclass to access protected method
    private static class TestableFactory extends BasicDeserializerFactory {
        protected TestableFactory() {
            super(null);
        }

        @Override
        public DeserializerFactory withConfig(DeserializerFactoryConfig config) {
            return this;
        }

        @Override
        public void _addExplicitAnyCreator(DeserializationContext ctxt, BeanDescription beanDesc, 
                                           CreatorCollector creators, CreatorCandidate candidate) 
                                           throws JsonMappingException {
            super._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        }

        // Mocking internal calls used by the method under test
        @Override
        protected void _addExplicitDelegatingCreator(DeserializationContext ctxt, BeanDescription beanDesc, 
                                                    CreatorCollector creators, CreatorCandidate candidate) {
            creators.addDelegatingCreator(candidate.creator());
        }

        @Override
        protected void _addExplicitPropertyCreator(DeserializationContext ctxt, BeanDescription beanDesc, 
                                                  CreatorCollector creators, CreatorCandidate candidate) {
            creators.addPropertyCreator(candidate.creator(), false, null);
        }

        @Override
        protected boolean _handleSingleArgumentCreator(CreatorCollector creators, AnnotatedWithParams ctor, 
                                                       boolean isCreator, boolean isVisible) {
            creators.addCreator(ctor);
            return true;
        }

        @Override
        protected SettableBeanProperty constructCreatorProperty(DeserializationContext ctxt, BeanDescription beanDesc, 
                                                               PropertyName name, int index, AnnotatedParameter param, 
                                                               JacksonInject.Value injectable) {
            return mock(SettableBeanProperty.class);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableFactory();
        ctxt = mock(DeserializationContext.class);
        beanDesc = mock(BeanDescription.class);
        creators = mock(CreatorCollector.class);
    }

    /**
     * Test Case 1: candidate.paramCount() != 1
     * Subcase A: findOnlyParamWithoutInjection returns >= 0 AND paramName is null -> Delegating Creator
     * Subcase B: findOnlyParamWithoutInjection returns >= 0 AND paramName is NOT null -> Property Creator
     * Subcase C: findOnlyParamWithoutInjection returns < 0 -> Property Creator
     */
    @Test
    public void testNotOneParameter() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        when(candidate.paramCount()).thenReturn(2);
        when(candidate.creator()).thenReturn(creator);

        // Subcase A: Delegating
        when(candidate.findOnlyParamWithoutInjection()).thenReturn(0);
        when(candidate.paramName(0)).thenReturn(null);
        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        verify(creators).addDelegatingCreator(creator);

        // Subcase B: Property Creator via paramName != null
        reset(creators);
        when(candidate.paramName(0)).thenReturn(new PropertyName("test"));
        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        verify(creators).addPropertyCreator(eq(creator), eq(false), any());

        // Subcase C: Property Creator via findOnlyParamWithoutInjection < 0
        reset(creators);
        when(candidate.findOnlyParamWithoutInjection()).thenReturn(-1);
        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        verify(creators).addPropertyCreator(eq(creator), eq(false), any());
    }

    /**
     * Test Case 2: candidate.paramCount() == 1
     * Subcase A: useProps is true (explicit paramName or injectId exists) -> addPropertyCreator
     * Subcase B: useProps is true (implicit name exists and couldSerialize) -> addPropertyCreator
     * Subcase C: useProps is false -> handleSingleArgumentCreator and removeConstructors
     */
    @Test
    public void testOneParameter() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        AnnotatedParameter param = mock(AnnotatedParameter.class);
        BeanPropertyDefinition paramDef = mock(BeanPropertyDefinition.class);
        POJOPropertyBuilder builder = mock(POJOPropertyBuilder.class);

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.creator()).thenReturn(creator);
        when(candidate.parameter(0)).thenReturn(param);
        when(candidate.propertyDef(0)).thenReturn(paramDef);
        // Mocking the cast in the code: ((POJOPropertyBuilder) paramDef).removeConstructors()
        // Since paramDef is a BeanPropertyDefinition, we must ensure the mock can be cast or use a real object.
        // In a real Jackson environment, paramDef is often a POJOPropertyBuilder.
        // For testing, we'll mock the behavior if possible or use a spy.

        // Subcase A: useProps via explicit name
        when(candidate.explicitParamName(0)).thenReturn(new PropertyName("name"));
        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));

        // Subcase B: useProps via implicit name + couldSerialize
        reset(creators);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.findImplicitParamName(0)).thenReturn(new PropertyName("implicit"));
        when(paramDef.couldSerialize()).thenReturn(true);
        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);
        verify(creators).addPropertyCreator(eq(creator), eq(true), any(SettableBeanProperty[].class));

        // Subcase C: useProps is false (Single argument creator)
        reset(creators);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.findImplicitParamName(0)).thenReturn(null);

        // To avoid ClassCastException in the last line of the method, we need paramDef to be a POJOPropertyBuilder
        // We'll create a real one or a spy that extends POJOPropertyBuilder
        POJOPropertyBuilder realBuilder = new POJOPropertyBuilder(mock(Annotated.class), "test");
        when(candidate.propertyDef(0)).thenReturn(realBuilder);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        verify(creators).addCreator(creator);
        // Verify removeConstructors was called on the builder
        // Since we can't easily verify internal state of POJOPropertyBuilder without reflection, 
        // we rely on the fact that the code reached that line without exception.
    }

    /**
     * Test Case 3: ensure the removal of constructors happens when paramDef is present
     */
    @Test
    public void testRemoveConstructors() throws JsonMappingException {
        CreatorCandidate candidate = mock(CreatorCandidate.class);
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        POJOPropertyBuilder builder = new POJOPropertyBuilder(mock(Annotated.class), "test");

        when(candidate.paramCount()).thenReturn(1);
        when(candidate.creator()).thenReturn(creator);
        when(candidate.parameter(0)).thenReturn(mock(AnnotatedParameter.class));
        when(candidate.propertyDef(0)).thenReturn(builder);
        when(candidate.explicitParamName(0)).thenReturn(null);
        when(candidate.injection(0)).thenReturn(null);
        when(candidate.findImplicitParamName(0)).thenReturn(null);

        factory._addExplicitAnyCreator(ctxt, beanDesc, creators, candidate);

        // If it reaches here without ClassCastException, the logic for paramDef != null is verified
        verify(creators).addCreator(creator);
    }
}
